begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions,pg_catalog;
select no_plan();
\ir helpers/polat_inbound_fixtures.sql
select pg_temp.polat_setup(2001);select pg_temp.polat_setup(2002);
create function pg_temp.polat_summary(n integer)returns jsonb language sql stable as $$select public.admin_polat_response_summary_v1(pg_temp.polat_id(n,'2000'),(clock_timestamp()at time zone 'UTC')::date,(clock_timestamp()at time zone 'UTC')::date+1)$$;
select set_config('request.jwt.claim.sub','61b01000-0000-4000-8000-000000000001',true);
select is(pg_temp.polat_summary(2001)->>'mode','SYNTHETIC','summary has synthetic provenance');
select is(pg_temp.polat_summary(2001)->>'financial_authority','NONE','summary cannot confer financial authority');
select is(pg_temp.polat_summary(2001)#>>'{counts,captured}','1','one persisted inbound is tracked');
select is(pg_temp.polat_summary(2001)#>>'{counts,eligible}','1','eligible-at-receipt denominator is explicit');
select is(pg_temp.polat_summary(2001)->>'coverage_gap','0','atomic capture leaves no persisted-source gap');
select is(pg_temp.polat_summary(2001)->>'ai_ack_rate','0.00000000000000000000','known zero acknowledgements with real denominator is zero');
select is(pg_temp.polat_summary(2001)#>>'{latency,p50_ms}',null,'missing ACK latency stays unknown');
select ok((pg_temp.polat_summary(2001)->>'complete')::boolean,'small source set is complete');
update private.polat_inbound_work set received_at=clock_timestamp()-interval '1 second'where tenant_id=pg_temp.polat_id(2001,'2000');
select pg_temp.polat_prepare(2001);select pg_temp.polat_outcome(2001,pg_temp.polat_id(2001,'9000'),'FAKE_ACK');
select is(pg_temp.polat_summary(2001)#>>'{counts,ai_acked}','1','real fake receipt increments acknowledged work once');
select is(pg_temp.polat_summary(2001)#>>'{counts,ai_responded}','1','current state count remains distinct from ACK history');
select is(pg_temp.polat_summary(2001)#>>'{latency,sample}','1','only evidenced response enters latency sample');
select ok((pg_temp.polat_summary(2001)#>>'{latency,p50_ms}')::numeric>=1000,'fixture clock establishes nonnegative response delay');
select pg_temp.polat_send(2001,'2');
select is((pg_temp.polat_summary(2001)->>'ai_ack_rate')::numeric,0.5::numeric,'new unanswered inbound changes denominator without duplicating ACK');
select private.polat_claim_human_fixture(pg_temp.polat_id(2001,'2000'),pg_temp.polat_conv(2001),pg_temp.polat_gen(2001));
select is(pg_temp.polat_summary(2001)#>>'{counts,human_owned}','1','current acknowledged native human control is projected');
select is((pg_temp.polat_summary(2001)->>'human_ownership_rate')::numeric,1::numeric,'human denominator includes acknowledged owner and pending handoffs');
select is(pg_temp.polat_summary(2001)#>>'{counts,ai_acked}','1','takeover does not erase earlier acknowledged evidence');
select is(pg_temp.polat_summary(2001)->>'coverage_gap','0','new inbound still has its own work record');
-- Deliberately simulate a missing capture in this rollback-only privileged fixture.
alter table public.messages disable trigger polat_inbound_coverage;
select pg_temp.polat_send(2001,'missing-capture');
alter table public.messages enable trigger polat_inbound_coverage;
select is(pg_temp.polat_summary(2001)->>'coverage_gap','1','missing tracking is detected rather than declared zero unowned');
select ok(length(pg_temp.polat_summary(2001)::text)<5000,'aggregate response size remains bounded');
select ok(not(pg_temp.polat_summary(2001)::text~'"(source_hash|body_hash|human_owner|provider_chat_id|lease_token)"[[:space:]]*:|PRIVATE'),'summary excludes sensitive evidence and identifiers');
select ok(position(pg_temp.polat_id(2001,'2000')::text in pg_temp.polat_summary(2001)::text)=0,'summary does not serialize tenant identity');
select throws_ok($$select public.admin_polat_response_summary_v1('ffffffff-0000-4000-8000-000000000001',current_date,current_date+1)$$,'42501',null,'wrong tenant denied uniformly');
select throws_ok($$select public.admin_polat_response_summary_v1(pg_temp.polat_id(2001,'2000'),current_date,current_date+91)$$,'22023',null,'window hard maximum is 90 days');
select throws_ok($$select public.admin_polat_response_summary_v1(pg_temp.polat_id(2001,'2000'),null,current_date+1)$$,'22023',null,'missing window rejected');
select throws_ok($$select public.admin_polat_response_summary_v1(pg_temp.polat_id(2001,'2000'),current_date,current_date)$$,'22023',null,'empty window rejected');
select set_config('request.jwt.claim.sub','61b01000-0000-4000-8000-000000000002',true);
select lives_ok($$select pg_temp.polat_summary(2001)$$,'support can inspect safe response evidence');
select set_config('request.jwt.claim.sub','61b01000-0000-4000-8000-000000000003',true);
select lives_ok($$select pg_temp.polat_summary(2001)$$,'analyst can inspect safe aggregates');
select set_config('request.jwt.claim.sub','61b01000-0000-4000-8000-000000000004',true);
select throws_ok($$select pg_temp.polat_summary(2001)$$,'42501',null,'readonly denied');
select set_config('request.jwt.claim.sub','',true);
select throws_ok($$select pg_temp.polat_summary(2001)$$,'42501',null,'anonymous denied');
select ok(not has_function_privilege('service_role','public.admin_polat_response_summary_v1(uuid,date,date)','EXECUTE'),'service role receives no extra read or writer capability');
select ok(not has_table_privilege('authenticated','private.polat_response_evidence','SELECT'),'raw private evidence remains inaccessible');
select set_config('request.jwt.claim.sub','61b01000-0000-4000-8000-000000000001',true);
do $$begin for i in 2..1005 loop perform pg_temp.polat_send(2002,i::text);end loop;end;$$;
select ok(not(pg_temp.polat_summary(2002)->>'complete')::boolean,'large history explicitly marks incompleteness');
select is(pg_temp.polat_summary(2002)#>>'{counts,captured}','1000','work collection has an independent hard bound');
select is(pg_temp.polat_summary(2002)->>'source_messages','1000','source messages have an independent hard bound');
select is(pg_temp.polat_summary(2002)->>'ai_ack_rate',null,'truncation cannot produce a misleading full-scope success rate');
select is(pg_temp.polat_summary(2002)->>'human_ownership_rate',null,'truncated human ratio remains unavailable');
select is(pg_temp.polat_summary(2002)#>>'{latency,p95_ms}',null,'truncated latency is unavailable');
select is((select count(*)from public.messages where tenant_id in(pg_temp.polat_id(2001,'2000'),pg_temp.polat_id(2002,'2000'))and direction='outbound'),0::bigint,'no actual outbound created');
select is((select count(*)from private.verified_payment_receipts where tenant_id in(pg_temp.polat_id(2001,'2000'),pg_temp.polat_id(2002,'2000'))),0::bigint,'no financial authority created');
select is((select count(*)from public.subscriptions where tenant_id in(pg_temp.polat_id(2001,'2000'),pg_temp.polat_id(2002,'2000'))),0::bigint,'no subscription authority created');
do $$declare started timestamptz:=clock_timestamp();v jsonb;p jsonb;body text;begin
 v:=pg_temp.polat_summary(2002);
 raise notice 'POLAT_SUMMARY_MEASUREMENT %',jsonb_build_object('mode','SYNTHETIC','source_rows',1005,'work_sample',v#>'{counts,captured}','complete',v->'complete','response_bytes',octet_length(v::text),'elapsed_ms',extract(epoch from(clock_timestamp()-started))*1000);
 execute format('explain(analyze,buffers,format json) select sequence from private.polat_inbound_work where tenant_id=%L and received_at>=current_date order by received_at desc,sequence desc limit 1001',pg_temp.polat_id(2002,'2000'))into p;
 raise notice 'POLAT_READ_PLAN %',p;
 body:=pg_get_functiondef('public.admin_polat_response_summary_v1(uuid,date,date)'::regprocedure);
 body:='with work_source'||split_part(split_part(body,'with work_source',2),'into result',1)||'from stats cross join bounds';
 body:=replace(replace(replace(body,'target_tenant_id',quote_literal(pg_temp.polat_id(2002,'2000'))||'::uuid'),'start_value','current_date'),'end_value','(current_date+1)');
 execute 'explain(analyze,buffers,format json)'||body into p;
 raise notice 'POLAT_FULL_READ_PLAN %',p;
end;$$;
select is((select sum(value::text::int)from jsonb_each(pg_temp.polat_summary(2001)->'counts')where key in('ai_pending','ai_responded','human_pending','human_owned','unknown','blocked','closed')),(pg_temp.polat_summary(2001)#>>'{counts,captured}')::bigint,'current-state distribution partitions captured evidence without ACK overlap');
select is(pg_temp.polat_summary(2001)#>>'{counts,human_owned}',(select count(*)::text from jsonb_array_elements(public.admin_polat_inbound_page_v1(pg_temp.polat_id(2001,'2000'))->'items')r where r->>'state'='HUMAN_OWNED'),'optimized summary agrees with accepted row projection');
select * from finish();
rollback;
